#include "chrome/browser/themes/autogenerated_theme_supplier.h"

#include "chrome/browser/themes/theme_properties.h"
#include "chrome/common/themes/autogenerated_theme_util.h"
#include "ui/gfx/color_palette.h"
#include "ui/gfx/color_utils.h"

namespace {

using TP = ThemeProperties;

}  // namespace

AutogeneratedThemeSupplier::AutogeneratedThemeSupplier()
    : CustomThemeSupplier(ThemeType::kAutogenerated) {}

AutogeneratedThemeSupplier::~AutogeneratedThemeSupplier() = default;

// static
scoped_refptr<AutogeneratedThemeSupplier>
AutogeneratedThemeSupplier::CreateForColor(SkColor color) {
  return CreateForColors(GetAutogeneratedThemeColors(color));
}

// static
scoped_refptr<AutogeneratedThemeSupplier>
AutogeneratedThemeSupplier::CreateForColors(
    const AutogeneratedThemeColors& colors) {
  auto supplier = base::MakeRefCounted<AutogeneratedThemeSupplier>();

  supplier->SetFrameColors(colors.frame_color);

  // Inactive tab uses frame color.
  supplier->SetColor(TP::COLOR_TAB_BACKGROUND_INACTIVE_FRAME_ACTIVE,
                     colors.frame_color);
  supplier->SetColor(TP::COLOR_TAB_FOREGROUND_INACTIVE_FRAME_ACTIVE,
                     colors.frame_text_color);

  // Toolbar and active tab use active tab color.
  supplier->SetColor(TP::COLOR_TOOLBAR, colors.active_tab_color);
  supplier->SetColor(TP::COLOR_TOOLBAR_TEXT, colors.active_tab_text_color);
  supplier->SetColor(TP::COLOR_TOOLBAR_BUTTON_ICON,
                     colors.active_tab_text_color);

  // NTP.
  supplier->SetColor(TP::COLOR_NTP_BACKGROUND, colors.ntp_color);
  supplier->SetColor(TP::COLOR_NTP_TEXT,
                     color_utils::GetColorWithMaxContrast(colors.ntp_color));

  // Always use alternate logo (not colorful one) for all backgrounds except
  // white.
  if (colors.active_tab_color != SK_ColorWHITE) {
    supplier->SetDisplayProperty(TP::NTP_LOGO_ALTERNATE, 1);
    SkColor logo_color = color_utils::IsDark(colors.ntp_color)
                             ? SK_ColorWHITE
                             : GetContrastingColor(colors.ntp_color,
                                                   /*luminosity_change=*/0.3f);
    supplier->SetColor(TP::COLOR_NTP_LOGO, logo_color);
  }

  supplier->SetFrameAndToolbarRelatedColors();
  return supplier;
}

// static
scoped_refptr<AutogeneratedThemeSupplier>
AutogeneratedThemeSupplier::CreateForWebAppColors(SkColor theme_color,
                                                  SkColor background_color) {
  auto supplier = base::MakeRefCounted<AutogeneratedThemeSupplier>();

  // Frame and inactive tab use the theme color.
  supplier->SetFrameColors(theme_color);
  supplier->SetColor(TP::COLOR_TAB_BACKGROUND_INACTIVE_FRAME_ACTIVE,
                     theme_color);
  SkColor theme_text_color = color_utils::GetColorWithMaxContrast(theme_color);
  supplier->SetColor(TP::COLOR_TAB_FOREGROUND_INACTIVE_FRAME_ACTIVE,
                     theme_text_color);

  // Toolbar also uses theme color.
  supplier->SetColor(TP::COLOR_TOOLBAR, theme_color);
  supplier->SetColor(TP::COLOR_TOOLBAR_TEXT, theme_text_color);
  supplier->SetColor(TP::COLOR_TOOLBAR_BUTTON_ICON, theme_text_color);

  // Active tab however uses background color.
  supplier->SetColor(TP::COLOR_TAB_BACKGROUND_ACTIVE_FRAME_ACTIVE,
                     background_color);
  supplier->SetColor(TP::COLOR_TAB_FOREGROUND_ACTIVE_FRAME_ACTIVE,
                     color_utils::GetColorWithMaxContrast(background_color));

  supplier->SetFrameAndToolbarRelatedColors();
  return supplier;
}

void AutogeneratedThemeSupplier::SetFrameColors(SkColor frame_color) {
  SetColor(TP::COLOR_FRAME_ACTIVE, frame_color);

  // Don't change frame color for inactive window.
  SetTint(TP::TINT_FRAME_INACTIVE, {-1, -1, -1});
  SetTint(TP::TINT_FRAME_INCOGNITO_INACTIVE, {-1, -1, -1});
  SetColor(TP::COLOR_FRAME_INACTIVE, frame_color);

  // Colors that BrowserThemePack derives from the frame color are omitted:
  //   - kColorWindowControlButtonBackground{Active,Inactive} are already
  //     defined as ui::kColorFrame{Active,Inactive} in chrome_color_mixer.cc.
  //     Recipe inputs resolve against this supplier's mixer, so they pick
  //     up the colors set above. BrowserThemePack only needs to compute them
  //     because a theme can supply its own button background color or image.
}

void AutogeneratedThemeSupplier::SetColor(int id, SkColor color) {
  colors_[id] = color;
}

void AutogeneratedThemeSupplier::SetTint(int id, color_utils::HSL tint) {
  tints_[id] = tint;
}

void AutogeneratedThemeSupplier::SetDisplayProperty(int id, int value) {
  display_properties_[id] = value;
}

bool AutogeneratedThemeSupplier::GetTint(int id, color_utils::HSL* hsl) const {
  auto it = tints_.find(id);
  if (it != tints_.end()) {
    *hsl = it->second;
    return true;
  }
  return false;
}

bool AutogeneratedThemeSupplier::GetColor(int id, SkColor* color) const {
  auto it = colors_.find(id);
  if (it != colors_.end()) {
    *color = it->second;
    return true;
  }
  return false;
}

bool AutogeneratedThemeSupplier::GetDisplayProperty(int id, int* result) const {
  auto it = display_properties_.find(id);
  if (it != display_properties_.end()) {
    *result = it->second;
    return true;
  }
  return false;
}
